CHANGES = json.loads(r'''{"APP-STORE-SUBMISSION.md":{"before":"2f0ee570a0a46417a8f96ca3c77e5c8e2649c77fde801bd99e24a8d48d62f136","after":"1af89dc5caa73c81ba54bdfa188129e87add804eee784531d3e092986485a45f","edits":[[2711,2984,"Apple-provider token revocation is still an unresolved release blocker: the audited deletion endpoint does not revoke Apple authorization. Complete a secure revocation/re-authentication implementation and test it with configured Apple credentials before claiming compliance","The current integration does not retain Apple provider credentials for automatic revocation. The September 6 follow-up implements the no-token fallback in Apple TN3194: complete account deletion, clear the local session, and show Apple disconnect instructions. This is not automatic token revocation. Verify the fallback on the signed build; secure provider-token capture/revocation for future sign-ins remains follow-up work, not deployed functionality"],[4910,4983,"authorization revocation implemented and verified during account deletion","deletion behavior verified on a signed build: current no-token fallback must show disconnect instructions and remove local auth. Automatic provider-token revocation is not enabled"],[6456,6456,"","\n### Apple deletion policy clarification — September 6 follow-up\n\nApple TN3194 explicitly documents fulfilling account deletion and directing manual Apple revocation when no provider credentials are available. Do not reject or postpone those deletion requests simply because no token is stored. Do not tell reviewers that manual guidance is automatic revocation. For future integrations, securely capture and validate Apple credentials server-side, implement revocation/notifications, and test with configured credentials. Reference: https://developer.apple.com/documentation/technotes/tn3194-handling-account-deletions-and-revoking-tokens-for-sign-in-with-apple\n"]]},"api/delete-account.js":{"before":"862c513ee0723580a2154e15c50f6f67b42ccded91e398e33a1fed2cb8affdcc","after":"b13576aa1f3452a2e1575f5e3c1f522aa823f7e9052ebb8f7b55cd3664e06d29","edits":[[3611,3611,"","// The current Supabase OAuth flow has no retained Apple provider token.\n// Apple's TN3194 says to fulfill deletion and direct these users to manual\n// revocation, not to block deletion or claim that a Supabase token is an Apple token.\nexport function appleDisconnectRequired(user) {\n  return (Array.isArray(user?.identities) && user.identities.some(identity => identity?.provider === \"apple\")) ||\n    user?.app_metadata?.provider === \"apple\" ||\n    (Array.isArray(user?.app_metadata?.providers) && user.app_metadata.providers.includes(\"apple\"));\n}\n\n"],[7310,7324," success: true","\n      success: true,\n      appleRevocation: appleDisconnectRequired(user) ? \"manual_required\" : \"not_applicable\"\n   "]]},"dashboard.html":{"before":"4e7a00bd128db98385e1a217db2e8050ae6947c90573edc52845c77053877dd1","after":"28fdbf81dc846b3513ec5ea3c56cd1e49105e7dbecb21bc479aaf823fcc7ef01","edits":[[65456,65456,""," Limited records may be retained as described in our Privacy Policy.</p><p>If you used Sign in with Apple, we will show how to disconnect Apple after your account is deleted."],[73161,73161,"","let accountDeletionInProgress=false,accountDeletionCompleted=false,authStorageKey='';\n"],[158777,159922,"event.preventDefault();const form=event.currentTarget,status=document.getElementById('delete-status'),button=form.querySelector('[type=\"submit\"]');if(form.confirmation.value!=='DELETE'){status.textContent='Type DELETE exactly to continue.';return}button.disabled=true;button.textContent='Deleting…';status.textContent='';try{const {data:{session},error:sessionError}=await activeClient.auth.getSession();if(sessionError||!session?.access_token)throw new Error('Your session expired. Please log in again.');const response=await fetch('/api/delete-account',{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({confirmation:'DELETE'})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'We could not delete your account.');await activeClient.auth.signOut({scope:'local'}).catch(()=>{});location.replace('/login?account=deleted')}catch(error){status.textContent=error.message||'We could not delete your account. Please try again.';button.disabled=false;button.textContent='Permanently delete account'}","\n  event.preventDefault();\n  if(accountDeletionInProgress)return;\n  const form=event.currentTarget,status=document.getElementById('delete-status'),button=form.querySelector('[type=\"submit\"]');\n  if(form.confirmation.value!=='DELETE'){status.textContent='Type DELETE exactly to continue.';return}\n  accountDeletionInProgress=true;button.disabled=true;button.textContent='Deleting…';status.textContent='';\n  try{\n    const {data:{session},error:sessionError}=await activeClient.auth.getSession();\n    if(sessionError||!session?.access_token)throw new Error('Your session expired. Please log in again.');\n    if(session.user.id!==currentUser.id)throw new Error('The signed-in account changed. Reload and review your account before deleting.');\n    const response=await fetch('/api/delete-account',{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({confirmation:'DELETE'})});\n    const result=await response.json().catch(()=>({}));\n    if(!response.ok||result.success!==true)throw new Error(result.error||'Account deletion was not confirmed. Please try again.');\n    // Only the authenticated endpoint can confirm deletion. Never infer it from a URL.\n    accountDeletionCompleted=true;\n    let localSignOutComplete=false;\n    try{\n      const latest=await activeClient.auth.getSession();\n      if(!latest.data.session||latest.data.session.user.id===session.user.id){\n        await activeClient.auth.stopAutoRefresh();\n        await activeClient.auth.signOut({scope:'local'}).catch(()=>{});\n        if(authStorageKey){\n          [authStorageKey,`${authStorageKey}-code-verifier`,`${authStorageKey}-user`].forEach(key=>localStorage.removeItem(key));\n          localSignOutComplete=true;\n        }\n      }\n    }catch{}\n    const receipt={createdAt:Date.now(),appleDisconnectRequired:result.appleRevocation==='manual_required',localSignOutComplete};\n    try{sessionStorage.setItem('bjm-deletion-receipt-v1',JSON.stringify(receipt))}catch{\n      // Storage failure must never hide confirmed deletion or retry the operation.\n      alert('Your BaristaMatch account was deleted.'+(receipt.appleDisconnectRequired?' Apple was not automatically disconnected. Follow the Apple instructions on the next page.':''));\n    }\n    location.replace('/account-deleted.html');\n  }catch(error){\n    status.textContent=error.message||'We could not delete your account. Please try again.';\n    button.disabled=false;button.textContent='Permanently delete account';\n  }finally{accountDeletionInProgress=false}\n"],[166966,167058,"const client=window.supabase.createClient(config.supabaseUrl,config.supabasePublishableKey);","authStorageKey=`sb-${new URL(config.supabaseUrl).hostname.split('.')[0]}-auth-token`;const client=window.supabase.createClient(config.supabaseUrl,config.supabasePublishableKey,{auth:{storageKey:authStorageKey}});"],[169531,169616,"client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT')location.replace('/')})","client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'&&!accountDeletionCompleted)location.replace('/')})"]]},"delete-account.html":{"before":"dc3319b5c1a5856e25e030ca5254255da2838c937f76e049671b674fc4a7cb56","after":"e61c3057ba6626c11849ff633872899091e312eaba3e6a0d001d59ad73b5d7e0","edits":[[2968,2968,"","  <section aria-labelledby=\"apple-account\">\n    <h2 id=\"apple-account\">Accounts using Sign in with Apple</h2>\n    <p>For accounts without a retained Apple authorization token, we still delete the BaristaMatch account and then provide <a href=\"/account-deleted.html\">instructions to disconnect Sign in with Apple</a>. Automatic Apple revocation is not claimed. You do not need to disconnect Apple before requesting deletion.</p>\n  </section>\n"]]},"mobile/app/settings.tsx":{"before":"13e52300a7f0e9d542c92e3f686301736fc4ff078860d89cbb1df72066ebe961","after":"402ef0a6f46301656bdd919eee91d052252b5df0e55143262ff18ff57787be17","edits":[[23,23,"","Ref, use"],[276,310,"{ supabase } from \"@/lib/supabase\"","AsyncStorage from '@react-native-async-storage/async-storage';\nimport { AUTH_STORAGE_KEY, supabase } from \"@/lib/supabase\";\nimport { clearDeletedSession, finishAccountDeletion, type DeletionResponse } from '@/lib/accountDeletion'"],[724,724,"","  const deletionBusy = useRef(false);\n"],[3550,3575,"and all account data now?","now? Limited records may be retained as described in the Privacy Policy. If you used Sign in with Apple, we will show how to disconnect Apple after deletion."],[3781,3781,"","    if (deletionBusy.current) return;\n    deletionBusy.current = true;\n"],[3820,4051,"await authenticatedApi<{ success: boolean }>(\"/delete-account\", { confirmation: \"DELETE\" });\n      await unregisterThisDeviceNotifications().catch(() => undefined);\n      await supabase.auth.signOut();\n      router.replace(\"/login\"","const { data: { session } } = await supabase.auth.getSession();\n      if (!session?.user) throw new Error('Your session expired. Please log in again.');\n      await finishAccountDeletion(\n        () => authenticatedApi<DeletionResponse>(\"/delete-account\", { confirmation: \"DELETE\" }, 'POST', session.user.id),\n        () => clearDeletedSession(supabase.auth, AsyncStorage, AUTH_STORAGE_KEY, session.user.id),\n      );\n      // Server deletion cascades device registrations; do not make authenticated\n      // cleanup calls with a user that no longer exists.\n      router.replace('/account-deleted'"],[4201,4201,"","deletionBusy.current = false; "]]},"mobile/lib/api.ts":{"before":"a7908c000a662d8cfd1ebb2b1b21913223d4c7f6ca0c1e0fc3d36e3addda1097","after":"a437eb923777e99e5c3d302fc10ca1588c625dd966f867abd590f8599d542675","edits":[[274,274,"",", expectedUserId?: string"],[449,449,"","  if (expectedUserId && session.user.id !== expectedUserId) throw new Error('The signed-in account changed. Please review the request again.');\n"]]},"mobile/lib/supabase.ts":{"before":"36f259fff46e7bd48f4dde8cc31ccb4c938525df234d738997a1bf45c8966a33","after":"ee5457875d9efdd0a8d2da79b47780f51a1916b573fd74dae30a2dc474408216","edits":[[439,439,"","// Explicitly preserve Supabase's default key so deletion can clear local auth\n// even when the now-deleted user's remote sign-out request fails.\nexport const AUTH_STORAGE_KEY = `sb-${new URL(supabaseUrl).hostname.split('.')[0]}-auth-token`;\n\n"],[541,541,"","    storageKey: AUTH_STORAGE_KEY,\n"]]}}''')
NEW_FILES = json.loads(r'''{"account-deleted.html":"c6e0296fedc1aef3d65ffd652681be4e59d9379b6516dcd89cb70b66dcf87626","account-deleted.js":"954dc1d5dc83f9389faf4aba854d1279b67d341645a7128cad03d7d63029075c","docs/APPLE-DELETION-FOLLOWUP-2026-09-06.md":"b2dd0f27da30da23caad1c04de80dc66cea2f8a456c7b1a10702c2e51bcceb14","mobile/app/account-deleted.tsx":"2feac405875f10105aface9a48fd4c479a3378cf78b9b8617bf380d82c12cd5f","mobile/lib/accountDeletion.ts":"e4f274d56f294240d2ad47e9ed620299d8a1ae15e3c5f6be345442aa1729bb3e","tests/apple-account-deletion.test.mjs":"6299d7bcb00de4fdca9bea359d80e919f99e2ecb26858ddea0a4f0b5510a01f3"}''')

def digest(data):
    return hashlib.sha256(data).hexdigest()

prepared = {}
for name, change in CHANGES.items():
    original = Path(name).read_bytes()
    assert digest(original) == change['before'], 'Source moved: ' + name
    text = original.decode('utf-8')
    for start, end, old, new in reversed(change['edits']):
        assert text[start:end] == old, 'Unexpected content: ' + name
        text = text[:start] + new + text[end:]
    assert digest(text.encode('utf-8')) == change['after'], 'Patch differs from tested version: ' + name
    prepared[name] = text.encode('utf-8')
for name, sha in NEW_FILES.items():
    assert digest(Path(name).read_bytes()) == sha, 'New file differs from tested version: ' + name
for name, content in prepared.items():
    Path(name).write_bytes(content)
print('Applied exact locally tested Apple deletion changes; no production action.')
